function corsHeaders(request) {
  const origin = request.headers.get('Origin') || '*';
  return {
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Methods': 'GET, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
  };
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const cors = corsHeaders(request);

    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: cors });
    }

    // Health check
    if (url.pathname === '/health') {
      return new Response(JSON.stringify({
        status: 'ok',
        service: 'tlc-landing',
        version: '2.0.0'
      }), {
        headers: { ...cors, 'Content-Type': 'application/json' }
      });
    }

    // Contact form submission
    if (request.method === 'POST' && url.pathname === '/contact') {
      try {
        const { name, email, message, category } = await request.json();
        if (!name || !email || !message) {
          return new Response(JSON.stringify({ error: 'Missing fields' }), { status: 400, headers: { ...cors, 'Content-Type': 'application/json' } });
        }
        if (!env.SENDGRID_API_KEY) {
          console.error('SENDGRID_API_KEY not set on landing worker');
          return new Response(JSON.stringify({ error: 'Email not configured' }), { status: 500, headers: { ...cors, 'Content-Type': 'application/json' } });
        }
        const html = `<div style="font-family:sans-serif;max-width:560px;margin:0 auto;padding:24px;">
          <h2 style="color:#2ea84a;margin-bottom:4px;">New Contact Form Submission</h2>
          <p style="color:#666;font-size:13px;margin-bottom:24px;">via thelongevitychef.io</p>
          <table style="width:100%;border-collapse:collapse;">
            <tr><td style="padding:10px 0;font-weight:700;color:#1a1a1a;width:80px;">Category</td><td style="padding:10px 0;color:#333;">${category || 'Not specified'}</td></tr>
            <tr><td style="padding:10px 0;font-weight:700;color:#1a1a1a;">Name</td><td style="padding:10px 0;color:#333;">${name}</td></tr>
            <tr><td style="padding:10px 0;font-weight:700;color:#1a1a1a;">Email</td><td style="padding:10px 0;color:#333;"><a href="mailto:${email}" style="color:#2ea84a;">${email}</a></td></tr>
            <tr><td style="padding:10px 0;font-weight:700;color:#1a1a1a;vertical-align:top;">Message</td><td style="padding:10px 0;color:#333;line-height:1.6;">${message.replace(/\n/g,'<br>')}</td></tr>
          </table>
        </div>`;
        const sgRes = await fetch('https://api.sendgrid.com/v3/mail/send', {
          method: 'POST',
          headers: {
            'Authorization': 'Bearer ' + env.SENDGRID_API_KEY,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            personalizations: [{ to: [{ email: 'chris@thelongevitychef.io' }] }],
            from: { email: 'chris@thelongevitychef.io', name: 'TLC Contact Form' },
            reply_to: { email: email, name: name },
            subject: `[${category || 'Contact'}] ${name}`,
            content: [{ type: 'text/html', value: html }],
          }),
        });
        if (sgRes.ok || sgRes.status === 202) {
          return new Response(JSON.stringify({ ok: true }), { status: 200, headers: { ...cors, 'Content-Type': 'application/json' } });
        }
        const err = await sgRes.text();
        console.error('SendGrid error:', err);
        return new Response(JSON.stringify({ error: 'Send failed' }), { status: 500, headers: { ...cors, 'Content-Type': 'application/json' } });
      } catch(e) {
        console.error('Contact handler error:', e);
        return new Response(JSON.stringify({ error: 'Server error' }), { status: 500, headers: { ...cors, 'Content-Type': 'application/json' } });
      }
    }

    if (request.method === 'GET') {
      const path = url.pathname.replace(/\/$/, '') || '/';
      let html;
      if (path === '/' || path === '') html = LANDING_HTML;
      else if (path === '/features') html = FEATURES_HTML;
      else if (path === '/how-it-works') html = HOW_IT_WORKS_HTML;
      else if (path === '/why-tlc') html = WHY_TLC_HTML;
      else if (path === '/pricing') html = PRICING_HTML;
      else if (path === '/start') html = START_HTML;
      else if (path === '/privacy') html = PRIVACY_HTML;
      else if (path === '/terms') html = TERMS_HTML;
      else if (path === '/assets/mona.jpg') {
        const res = await fetch('https://cdn.jsdelivr.net/gh/cwilsonjbh/tlc-landing@master/assets/mona.jpg');
        if (!res.ok) return new Response('Not Found', { status: 404, headers: cors });
        const data = await res.arrayBuffer();
        return new Response(data, { headers: { 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=86400, s-maxage=604800', 'Access-Control-Allow-Origin': '*' } });
      }
      else if (path === '/assets/logo.png') {
        const res = await fetch('https://cdn.jsdelivr.net/gh/cwilsonjbh/tlc-landing@master/assets/logo.png');
        if (!res.ok) return new Response('Not Found', { status: 404, headers: cors });
        const data = await res.arrayBuffer();
        return new Response(data, { headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=86400, s-maxage=604800', 'Access-Control-Allow-Origin': '*' } });
      }
      else {
        return new Response('Not Found', { status: 404, headers: cors });
      }

      return new Response(html, {
        headers: {
          ...cors,
          'Content-Type': 'text/html;charset=UTF-8',
          'Cache-Control': 'public, max-age=300',
        }
      });
    }

    return new Response('Not Found', { status: 404, headers: cors });
  }
};
